ПУТЬ = r"C:\\sender\\sender\\ai_letter.py"
т = io.open(ПУТЬ, encoding="utf-8").read()
if "_ПРО_ТЕКСТ_ПИСЬМА" in т:
    print("=== НЕ ПОКУПАТЕЛЬ ПРО ТЕКСТ: УЖЕ БЫЛО ===")
    sys.exit(0)
ПАРЫ = [('Претензию по пунктам 1 и 2 начинай словами "НЕ ПОКУПАТЕЛЬ: " - такое письмо\nправкой текста не спасти.\nЕСЛИ КОМПАНИЯ НЕ НАШ ПОКУПАТЕЛЬ ПО ЭТОМУ НАПРАВЛЕНИЮ, НО ГОДИТСЯ ДРУГОМУ -\nпоставь в поле drugoe значение "kc". Другое направление - компрессоры,\n', 'Претензию по пунктам 1 и 2 начинай словами "НЕ ПОКУПАТЕЛЬ: " - такое письмо\nправкой текста не спасти.\n"НЕ ПОКУПАТЕЛЬ" - ТОЛЬКО ПРО САМУ КОМПАНИЮ (разбор 13.10). Претензия к тому,\nчто ОБЕЩАЕТ ПИСЬМО (что рентген или фотосепаратор найдёт или не найдёт -\nволос, силикон, «плотные включения»; неточный технологический факт), и\nвыдумка по пункту 3 - это претензия к ТЕКСТУ: пиши её без слов\n"НЕ ПОКУПАТЕЛЬ", письмо поправят.\nЕСЛИ КОМПАНИЯ НЕ НАШ ПОКУПАТЕЛЬ ПО ЭТОМУ НАПРАВЛЕНИЮ, НО ГОДИТСЯ ДРУГОМУ -\nпоставь в поле drugoe значение "kc". Другое направление - компрессоры,\n'), ('# Метка безнадёжного письма: правкой текста адресата не исправить.\nНЕ_ПОКУПАТЕЛЬ = "НЕ ПОКУПАТЕЛЬ"\n\n# «обе» — технолог и скептик в одном вызове (18.08). Две линзы читают одно и\n', '# Метка безнадёжного письма: правкой текста адресата не исправить.\nНЕ_ПОКУПАТЕЛЬ = "НЕ ПОКУПАТЕЛЬ"\n# Претензия к тексту письма, а не к компании (разбор 13.10): такая метка\n# НЕ ПОКУПАТЕЛЬ ошибочна, письмо идёт в починку.\n_ПРО_ТЕКСТ_ПИСЬМА = re.compile(\n    r\'обеща|небезопасн|(?:рентген|сепаратор|машин|инспекц)\\w*[^.;]{0,40}(?:наход|найд|видит|выявля|обнаружива)|\'\n    r\'приписан|сказано то, чего нет|в письме|письмо (?:обеща|утвержда|пишет)|\'\n    r\'формулир|плотн\\w* включени|силикон|волос\', re.I)\n\n# «обе» — технолог и скептик в одном вызове (18.08). Две линзы читают одно и\n'), ("        # лечит, а стоит вызова — и, что хуже, чинилка вернёт гладкое письмо\n        # и заслон его пропустит. Такие бракуем сразу и с причиной.\n        безнадёжные = {i: п for i, п in плохие.items()\n                       if НЕ_ПОКУПАТЕЛЬ in str(п or '')}\n", "        # лечит, а стоит вызова — и, что хуже, чинилка вернёт гладкое письмо\n        # и заслон его пропустит. Такие бракуем сразу и с причиной.\n        # Разбор 13.10: в одном вызове трёх линз претензия ТЕХНОЛОГА к тексту\n        # («рентген не найдёт волос/силикон») приходила с меткой НЕ ПОКУПАТЕЛЬ —\n        # 62 письма за день ушли в брак без починки, среди них мясокомбинаты.\n        # Претензию к тексту отдаём чинилке, метку снимаем.\n        for i, п in list(плохие.items()):\n            if НЕ_ПОКУПАТЕЛЬ in str(п or '') and _ПРО_ТЕКСТ_ПИСЬМА.search(str(п).split(НЕ_ПОКУПАТЕЛЬ, 1)[-1]):\n                плохие[i] = str(п).replace(НЕ_ПОКУПАТЕЛЬ + ':', '').replace(НЕ_ПОКУПАТЕЛЬ, '').strip()\n        безнадёжные = {i: п for i, п in плохие.items()\n                       if НЕ_ПОКУПАТЕЛЬ in str(п or '')}\n")]
for с, _н in ПАРЫ:
    if т.count(с) != 1:
        print("якорь (%d): %r" % (т.count(с), с[:120]))
        print("=== НЕ ПОКУПАТЕЛЬ ПРО ТЕКСТ: НЕ ПРИМЕНЕНО ===")
        sys.exit(0)
бэкап = ПУТЬ + ".bak-%d" % int(time.time())
shutil.copy2(ПУТЬ, бэкап)
for с, н in ПАРЫ:
    т = т.replace(с, н)
io.open(ПУТЬ, "w", encoding="utf-8").write(т)
try:
    py_compile.compile(ПУТЬ, doraise=True)
except Exception as е:  # noqa: BLE001
    shutil.copy2(бэкап, ПУТЬ)
    print("сбой, откат: %s" % е)
    print("=== НЕ ПОКУПАТЕЛЬ ПРО ТЕКСТ: ОТКАТ ===")
    sys.exit(0)
print("бэкап: %s" % бэкап)
print("=== НЕ ПОКУПАТЕЛЬ ПРО ТЕКСТ: ПРИМЕНЕНО ===")
